#!/usr/bin/env bash
# Run the one-dimensional (Q^2-only) study: every XML below xml/oned_study/<family>/<variant>/,
# generated by python/scripts/make_oned_study_xmls.py. Same options and environment as
# xml/binning_study/run_all.sh; results go to OUTPUT_ROOT/oned_study_fit_results/<family>/<variant>/<fit>/.
script_dir="$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")" && pwd)"
STUDY_DIR="${script_dir}" STUDY_NAME="oned_study" exec "${script_dir}/../binning_study/run_all.sh" "$@"
